def transform(g):
    g=[row[:] for row in g]; h,w=len(g),len(g[0])
    centers=[(r,c) for r in range(1,h-1) for c in range(1,w-1)
             if g[r][c]==2 and g[r-1][c]==3==g[r+1][c] and g[r][c-1]==3==g[r][c+1]]
    def is_vline(c,r0,r1):
        return all(g[r][c]==2 for r in range(h) if not (r0-1<=r<=r1+1))
    def is_hline(r,c0,c1):
        return all(g[r][c]==2 for c in range(w) if not (c0-1<=c<=c1+1))
    info=[]
    for (r,c) in centers:
        if is_vline(c,r,r): orient='v'
        elif is_hline(r,c,c): orient='h'
        else: orient=None
        info.append((r,c,orient))
    # partner: other block center row; if single block, nearest other full 2-line
    other_lines=[]
    for r in range(h):
        if all(g[r][c]==2 for c in range(w)): other_lines.append(('h',r))
    for c in range(w):
        if all(g[r][c]==2 for r in range(h)): other_lines.append(('v',c))
    for i,(r,c,orient) in enumerate(info):
        others=[(rr,cc) for j,(rr,cc,o) in enumerate(info) if j!=i]
        if others:
            pr=min(others,key=lambda p:abs(p[0]-r))[0]
        else:
            cand=[x for o,x in other_lines if not (o=='h' and x==r) and not (o=='v' and x==c)]
            pr=min(cand,key=lambda x:abs(x-r))
        pr_,pc_=pr,c
        # 3x3 square
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                if dr==0 and dc==0: continue
                rr,cc=pr_+dr,pc_+dc
                if 0<=rr<h and 0<=cc<w: g[rr][cc]=1
        # bar perpendicular to own line
        if orient=='v': cells=[(pr_,cc) for cc in range(w)]
        else: cells=[(rr,pc_) for rr in range(h)]
        for (rr,cc) in cells:
            if (rr,cc)==(pr_,pc_): continue
            if any((rr,cc)==(br,bc) for br,bc in centers): continue
            if g[rr][cc]==3 and min(max(abs(rr-br),abs(cc-bc)) for br,bc in centers)<=1: continue
            g[rr][cc]=1
    return g

